import json, re, unicodedata
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
DATE='2026-09-21'
INITIAL_REVIEW_DATE=DATE
UPDATED='2026-09-22'
NV='Needs verification'
GAPS=['Cross-dataset validation','Temporal robustness','Open-world recognition','Unknown applications','Concept drift','Data leakage control','Minority-class performance','False-negative analysis','Calibration','Explainability','Real-time throughput','Edge deployment','Energy consumption','Privacy','Reproducibility','Code/checkpoint availability']
P=[]; E=[]; R=[]; D=[]
FIELDS=['Research problem','Traffic unit definition','Input representation','Packets / bytes','Payload','Header','Timing','Direction','Packet length','Preprocessing / anonymisation','Architecture','Pretraining objective','Fine-tuning objective','Supervision','Pretraining datasets','Training / evaluation datasets','Split strategy','Evaluation setting','Metrics','Reported results','Parameters','FLOPs','Latency','Throughput','Memory','Energy','Reproducibility','Leakage / shortcut risks','Deployment limitations','Version notes']
def evidence(pid,kind,text,url,locator='Abstract / bibliographic record',status='Verified',source_type='Original paper'):
    key=f'e{len(E)+1:04d}'
    E.append(dict(id=key,paperId=pid,category=kind,text=text,sourceUrl=url,sourceType=source_type,locator=locator,status=status,accessed=DATE)); return key

def add(id,short,title,authors,year,venue,url,family,unit,summary,contribution,risk,gap,**kw):
    details={k:NV for k in FIELDS};details.update(kw.pop('details',{}))
    eid=evidence(id,'Paper claim',summary+' '+contribution,url,kw.get('locator','Abstract / bibliographic record'))
    mid=evidence(id,'Bibliography',f'{title}. {venue}; {year}. Byline checked against the linked source.',url)
    iid=evidence(id,'Curator interpretation',risk+' Open question: '+gap,url,kw.get('locator','Scope of the reviewed abstract; not an independently reproduced finding'),status='Needs verification')
    p=dict(id=id,short=short,title=title,authors=authors.split('|'),year=year,venue=venue,url=url,family=family,unit=unit,summary=summary,contribution=contribution,limitation=risk,gap=gap,details=details,code=None,datasets=[],techniques=[],encrypted='Yes',payload=NV,pretraining='No',openWorld=NV,crossDataset=NV,deployment=NV,reproducibility='Metadata checked',seminal=False,publicationStatus='Peer reviewed',verification={'bibliography':'Verified','technical':'Needs verification'},evidenceIds=[mid,eid,iid],gaps={},reviewDepth='Metadata and abstract',**{})
    p.update(kw)
    p.setdefault('task','Traffic classification')
    for name in GAPS:p['gaps'][name]=dict(state='Not addressed/not reported',evidence=[eid],note='Not established in the reviewed evidence. This is an evidence gap, not proof of absence from the paper.')
    P.append(p);return p

DETAIL_RECORDS={}  # full-text evidence id -> (paper id, fields it supports)
def detail(pid,values,url,locator):
    p=next(p for p in P if p['id']==pid);p['details'].update(values)
    e=evidence(pid,'Paper claim','; '.join(k+': '+v for k,v in values.items()),url,locator)
    DETAIL_RECORDS[e]=(pid,dict(values))
    p['evidenceIds'].append(e);p['reviewDepth']='Selected full-text sections'
    if 'Reported results' in values:
        p['evidenceIds'].append(evidence(pid,'Author-reported result',values['Reported results'],url,locator))
    return e

def gapstate(pid,names,state,note,eid=None):
    p=next(p for p in P if p['id']==pid)
    for name in names.split('|'):p['gaps'][name]=dict(state=state,note=note,evidence=[eid or p['evidenceIds'][1]])

